import { getSession } from "@/lib/auth";

export async function GET() {
  const session = await getSession();
  const memberIds: string[] = session.team.memberIds;

  const members = await Promise.all(
    memberIds.map(async (id) => {
      const res = await fetch(`https://directory.example.com/api/people/${id}`, {
        headers: { authorization: `Bearer ${process.env.DIRECTORY_TOKEN}` },
      });
      return res.json();
    }),
  );

  return NextResponse.json({ members });
}

