import pMap from "p-map";
import sharp from "sharp";

export async function fetchImages(urls: string[]) {
  return pMap(
    urls,
    async (url) => {
      const res = await fetch(url);
      return sharp(Buffer.from(await res.arrayBuffer())).resize(256).toBuffer();
    },
    { concurrency: 4 },
  );
}

