const BATCH_SIZE = 20;

export async function backfill(docs: { id: string; text: string }[]) {
  for (let i = 0; i < docs.length; i += BATCH_SIZE) {
    const batch = docs.slice(i, i + BATCH_SIZE);
    await Promise.all(
      batch.map(async (doc) => {
        const embedding = await openai.embeddings.create({ model: "text-embedding-3-small", input: doc.text });
        await db.embedding.upsert({ where: { docId: doc.id }, create: { docId: doc.id, vector: embedding.data[0].embedding }, update: {} });
      }),
    );
  }
}

export async function linkPreviews(urls: string[]) {
  const firstFew = urls.slice(0, 3);
  return Promise.all(firstFew.map(async (u) => (await fetch(`/api/unfurl?url=${encodeURIComponent(u)}`)).json()));
}

import { compile } from "@mdx-js/mdx";

export async function renderPosts(posts: { slug: string; body: string }[]) {
  return Promise.all(
    posts.map(async (post) => ({ slug: post.slug, code: String(await compile(post.body, { outputFormat: "function-body" })) })),
  );
}

export async function refundAll(chargeIds: string[]) {
  const refunded: string[] = [];
  for (const id of chargeIds) {
    const refund = await stripe.refunds.create({ charge: id });
    refunded.push(refund.id);
  }
  return refunded;
}

export function formatCents(cents: number, currency = "USD", locale = "en-US"): string {
  return new Intl.NumberFormat(locale, { style: "currency", currency }).format(cents / 100);
}

export function sumCents(values: number[]): number {
  return values.reduce((acc, v) => acc + v, 0);
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET(_req: Request, { params }: { params: { id: string } }) {
  const user = await prisma.user.findUnique({ where: { id: params.id }, select: { id: true, name: true, email: true } });
  if (!user) return NextResponse.json({ error: "not found" }, { status: 404 });
  return NextResponse.json(user);
}

